'use client';

/**
 * Application preparation panel.
 *
 * One job, one action: build the material this application actually needs. The
 * panel is deliberately explicit about three things:
 *
 *  - what will be produced and why (the deterministic plan),
 *  - what already exists, so nothing is regenerated by accident,
 *  - the state of every independent task, including failures and retries.
 *
 * It never claims a document was produced until the server recorded a result
 * id, and it never marks anything as submitted.
 */

import Link from 'next/link';
import { useCallback, useEffect, useRef, useState } from 'react';
import {
  AlertCircle,
  ArrowRight,
  CheckCircle2,
  Circle,
  FileText,
  Info,
  Loader,
  RefreshCw,
  Sparkles,
} from 'lucide-react';

import type {
  PreparationPlan,
  PreparationRunSnapshot,
  PreparationStatus,
  PreparationTaskSnapshot,
  PreparationTaskType,
} from '@/lib/application-preparation/types';

const RECOMMENDATION_STYLES: Record<string, string> = {
  REQUIRED: 'bg-warn/15 text-warn-text border-warn/30',
  RECOMMENDED: 'bg-accent/15 text-accent-text border-accent/30',
  OPTIONAL: 'bg-surface-sunken text-muted border-line',
  NOT_NEEDED: 'bg-surface-sunken text-muted border-line',
};

const STATUS_STYLES: Record<string, string> = {
  COMPLETED: 'text-success-text',
  RUNNING: 'text-accent-text',
  FAILED: 'text-danger-text',
  SKIPPED: 'text-warn-text',
  PENDING: 'text-muted',
  CANCELLED: 'text-muted',
};

function taskIcon(task: PreparationTaskSnapshot) {
  if (task.status === 'COMPLETED') return <CheckCircle2 className="h-4 w-4 shrink-0 text-success-text" />;
  if (task.status === 'RUNNING') return <Loader className="h-4 w-4 shrink-0 animate-spin text-accent-text" />;
  if (task.status === 'FAILED') return <AlertCircle className="h-4 w-4 shrink-0 text-danger-text" />;
  if (task.status === 'SKIPPED') return <Info className="h-4 w-4 shrink-0 text-warn-text" />;
  return <Circle className="h-4 w-4 shrink-0 text-muted" />;
}

function runStatusLabel(status: PreparationRunSnapshot['status']): string {
  switch (status) {
    case 'QUEUED':
      return 'Ready to continue';
    case 'RUNNING':
      return 'Preparing…';
    case 'COMPLETED':
      return 'All materials ready';
    case 'PARTIALLY_COMPLETED':
      return 'Some materials need attention';
    case 'FAILED':
      return 'Preparation failed';
    case 'CANCELLED':
      return 'Cancelled';
  }
}

export function PreparationPanel({ jobId }: { jobId: string }) {
  const [status, setStatus] = useState<PreparationStatus | null>(null);
  const [run, setRun] = useState<PreparationRunSnapshot | null>(null);
  const [selected, setSelected] = useState<PreparationTaskType[]>([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);
  const [advancing, setAdvancing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const applyStatus = useCallback((next: PreparationStatus) => {
    setStatus(next);
    setRun(next.run);
    const defaults = next.plan.items
      .filter(
        (item) =>
          item.available &&
          item.selectedByDefault &&
          // The server is the authority; this only mirrors its plan.
          (item.type === 'RESUME_TAILORING' ||
            item.type === 'COVER_LETTER' ||
            item.type === 'RECRUITER_MESSAGE' ||
            item.type === 'INTERVIEW_BRIEFING'),
      )
      .map((item) => item.type);
    setSelected(
      next.run && !next.run.terminal
        ? (next.run.requestedTasks as PreparationTaskType[])
        : defaults,
    );
  }, []);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/jobs/${encodeURIComponent(jobId)}/preparation`, {
        cache: 'no-store',
      });
      const payload = await response.json().catch(() => null);
      if (!mounted.current) return;
      if (!response.ok) {
        setError(payload?.error?.message ?? 'Could not load preparation options.');
        return;
      }
      applyStatus(payload as PreparationStatus);
    } catch {
      if (mounted.current) setError('Could not load preparation options.');
    } finally {
      if (mounted.current) setLoading(false);
    }
  }, [applyStatus, jobId]);

  useEffect(() => {
    void load();
  }, [load]);

  const plan: PreparationPlan | null = status?.plan ?? null;
  const maxTasks = plan?.limits.maxTasksPerRun ?? 4;

  function toggle(type: PreparationTaskType) {
    setError(null);
    setNotice(null);
    setSelected((current) => {
      if (current.includes(type)) return current.filter((entry) => entry !== type);
      if (current.length >= maxTasks) {
        setNotice(`You can prepare up to ${maxTasks} materials in one run.`);
        return current;
      }
      return [...current, type];
    });
  }

  /**
   * Execute tasks one advance call at a time. Each call is a separate request,
   * so a refresh between calls loses only the step in flight — everything
   * already recorded stays recorded.
   */
  const advance = useCallback(async (runId: string) => {
    setAdvancing(true);
    setError(null);
    setNotice(null);
    try {
      for (let iteration = 0; iteration < 8; iteration += 1) {
        const response = await fetch(
          `/api/preparation/runs/${encodeURIComponent(runId)}/advance`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ maxTasks: 1 }),
          },
        );
        const payload = await response.json().catch(() => null);
        if (!mounted.current) return;
        if (!response.ok) {
          setError(payload?.error?.message ?? 'Preparation could not continue. Your finished materials are safe.');
          return;
        }

        const nextRun = payload?.run as PreparationRunSnapshot;
        setRun(nextRun);
        setStatus((current) => (current ? { ...current, run: nextRun } : current));

        if (!payload?.executed) {
          if (payload?.retryScheduled) {
            setNotice('A task will retry shortly. Press Continue preparation to try again now.');
          }
          return;
        }
        if (nextRun.terminal) return;
        if (payload?.retryScheduled) {
          setNotice('A task failed and will retry. Finished materials are kept.');
          return;
        }
      }
    } catch {
      if (mounted.current) {
        setError('Preparation was interrupted. Press Continue preparation to resume; finished materials are safe.');
      }
    } finally {
      if (mounted.current) setAdvancing(false);
    }
  }, []);

  async function prepare() {
    if (!plan) return;
    setCreating(true);
    setError(null);
    setNotice(null);
    try {
      const response = await fetch(`/api/jobs/${encodeURIComponent(jobId)}/preparation`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tasks: selected }),
      });
      const payload = await response.json().catch(() => null);
      if (!mounted.current) return;
      if (!response.ok) {
        setError(payload?.error?.message ?? 'Preparation could not start.');
        return;
      }
      const nextRun = payload.run as PreparationRunSnapshot;
      setRun(nextRun);
      setStatus((current) => (current ? { ...current, run: nextRun } : current));
      if (nextRun.terminal) {
        setNotice('Everything in this run was already prepared.');
        return;
      }
      await advance(nextRun.id);
    } catch {
      if (mounted.current) setError('Preparation could not start. Nothing was charged.');
    } finally {
      if (mounted.current) setCreating(false);
    }
  }

  async function resume() {
    if (!run) return;
    await advance(run.id);
  }

  if (loading) {
    return (
      <div className="card-pad flex items-center gap-2 text-sm text-muted">
        <Loader className="h-4 w-4 animate-spin" /> Loading preparation options…
      </div>
    );
  }

  if (error && !plan) {
    return (
      <div className="card-pad space-y-3">
        <div className="flex items-start gap-2 text-sm text-danger-text">
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
          <span>{error}</span>
        </div>
        <button type="button" className="btn-secondary gap-1.5 text-sm" onClick={() => void load()}>
          <RefreshCw className="h-3.5 w-3.5" /> Try again
        </button>
      </div>
    );
  }

  if (!plan) return null;

  const runInProgress = Boolean(run && !run.terminal);
  const canStart =
    plan.canPrepare && selected.length > 0 && !creating && !advancing && !runInProgress;
  const completedCount = run?.tasks.filter((task) => task.status === 'COMPLETED').length ?? 0;
  const runnable = run?.hasRunnableTask ?? false;

  return (
    <section className="card-pad space-y-5">
      <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
        <div className="min-w-0">
          <h2 className="flex items-center gap-2 text-lg font-semibold text-ink">
            <Sparkles className="h-4 w-4 text-accent-text" />
            Application preparation
          </h2>
          <p className="mt-1 max-w-2xl text-sm leading-6 text-muted">
            Build the materials this application needs. Each item runs independently, so a slow or
            failed step never discards work that already succeeded.
          </p>
        </div>
        {run ? (
          <span className="shrink-0 rounded-full border border-line px-3 py-1 text-xs font-medium text-muted">
            {runStatusLabel(run.status)}
            {run.tasks.length > 0 ? ` · ${completedCount}/${run.tasks.length}` : ''}
          </span>
        ) : null}
      </div>

      <div className="rounded-xl border border-line bg-surface-sunken px-4 py-3 text-sm">
        <span className="text-muted">Starting point: </span>
        {plan.sourceResume.kind === 'STRUCTURED_RESUME' && plan.sourceResume.resumeId ? (
          <Link
            href={`/resumes/${plan.sourceResume.resumeId}`}
            className="font-medium text-accent-text hover:underline"
          >
            {plan.sourceResume.name}
          </Link>
        ) : (
          <span className="font-medium text-ink">
            {plan.sourceResume.kind === 'PROFILE' ? 'Your confirmed career profile' : 'Nothing available yet'}
          </span>
        )}
        <span className="block text-xs leading-5 text-muted">{plan.sourceResume.reason}</span>
      </div>

      {plan.blockers.length > 0 ? (
        <div className="space-y-1 rounded-xl border border-warn/30 bg-warn/10 px-4 py-3 text-sm text-warn-text">
          {plan.blockers.map((blocker) => (
            <p key={blocker} className="flex items-start gap-2">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
              <span>{blocker}</span>
            </p>
          ))}
        </div>
      ) : null}

      <div className="grid gap-3 md:grid-cols-2">
        {plan.items.map((item) => {
          const isSelected = selected.includes(item.type);
          const disabled = !item.available || runInProgress || creating || advancing;
          return (
            <div
              key={item.type}
              className={`rounded-xl border px-4 py-3 transition-colors ${
                isSelected ? 'border-accent/40 bg-accent/[0.06]' : 'border-line bg-surface'
              }`}
            >
              <div className="flex items-start justify-between gap-3">
                <label className="flex min-w-0 cursor-pointer items-start gap-2.5">
                  <input
                    type="checkbox"
                    className="mt-0.5 h-4 w-4 shrink-0 accent-accent"
                    checked={isSelected}
                    disabled={disabled}
                    onChange={() => toggle(item.type)}
                  />
                  <span className="min-w-0">
                    <span className="block text-sm font-medium text-ink">{item.label}</span>
                    <span className="mt-0.5 block text-xs leading-5 text-muted">{item.reason}</span>
                  </span>
                </label>
                <span
                  className={`shrink-0 rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${
                    RECOMMENDATION_STYLES[item.recommendation] ?? RECOMMENDATION_STYLES.OPTIONAL
                  }`}
                >
                  {item.available ? item.recommendation.toLowerCase() : 'not automated'}
                </span>
              </div>

              <div className="mt-2 flex flex-wrap items-center justify-between gap-2 border-t border-line pt-2 text-xs">
                <span className="text-muted">~{item.estimatedMinutes} min</span>
                {item.existing ? (
                  <Link
                    href={item.existing.href}
                    className="inline-flex items-center gap-1 font-medium text-accent-text hover:underline"
                  >
                    <FileText className="h-3 w-3" /> {item.existing.title}
                  </Link>
                ) : !item.available ? (
                  <span className="text-muted">Available from its own workspace</span>
                ) : null}
              </div>
            </div>
          );
        })}
      </div>

      {run && run.tasks.length > 0 ? (
        <div className="space-y-2 rounded-xl border border-line bg-surface-sunken px-4 py-3">
          {run.tasks.map((task) => (
            <div key={task.id} className="flex flex-wrap items-start justify-between gap-2 text-sm">
              <div className="flex min-w-0 items-start gap-2">
                {taskIcon(task)}
                <div className="min-w-0">
                  <span className="font-medium text-ink">{task.label}</span>
                  <span className={`ml-2 text-xs ${STATUS_STYLES[task.status] ?? 'text-muted'}`}>
                    {task.status.toLowerCase()}
                    {task.attempts > 0 ? ` · attempt ${task.attempts}/${task.maxAttempts}` : ''}
                  </span>
                  {task.errorMessage ? (
                    <p className="mt-0.5 text-xs leading-5 text-danger-text">{task.errorMessage}</p>
                  ) : null}
                </div>
              </div>
              {task.resultHref ? (
                <Link
                  href={task.resultHref}
                  className="inline-flex shrink-0 items-center gap-1 text-xs font-medium text-accent-text hover:underline"
                >
                  Open <ArrowRight className="h-3 w-3" />
                </Link>
              ) : null}
            </div>
          ))}
        </div>
      ) : null}

      {error ? (
        <p className="flex items-start gap-2 text-sm text-danger-text">
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" /> {error}
        </p>
      ) : null}
      {notice ? <p className="text-sm text-warn-text">{notice}</p> : null}

      <div className="flex flex-col gap-2 border-t border-line pt-4 sm:flex-row sm:items-center sm:justify-between">
        <p className="text-xs leading-5 text-muted">
          Nothing is marked as applied. Submission and its evidence stay a separate, explicit step.
        </p>
        <div className="flex flex-wrap gap-2">
          {run && runnable && !run.terminal ? (
            <button
              type="button"
              className="btn-primary gap-1.5 text-sm"
              disabled={advancing || creating}
              onClick={() => void resume()}
            >
              {advancing ? (
                <>
                  <Loader className="h-3.5 w-3.5 animate-spin" /> Preparing…
                </>
              ) : (
                <>
                  <RefreshCw className="h-3.5 w-3.5" /> Continue preparation
                </>
              )}
            </button>
          ) : null}
          <button
            type="button"
            className={run && runnable && !run.terminal ? 'btn-secondary gap-1.5 text-sm' : 'btn-primary gap-1.5 text-sm'}
            disabled={!canStart}
            onClick={() => void prepare()}
          >
            {creating || advancing ? (
              <>
                <Loader className="h-3.5 w-3.5 animate-spin" /> Preparing…
              </>
            ) : (
              <>
                <Sparkles className="h-3.5 w-3.5" />
                {run?.terminal ? 'Prepare again' : 'Prepare my application'}
              </>
            )}
          </button>
        </div>
      </div>
    </section>
  );
}
